"""Add a certified precision/work planner to the existing response reader."""
from fractions import Fraction as F
import hashlib,json
import markdown
from chemistry_budget_data import AREA,DATA,payload,replay,VERIFY

PROOF='read/computational-chemistry/precision-planning.html'
def add(site,body):
    raw=payload(site.root)
    if (site.root/DATA).read_bytes()!=raw:raise ValueError('Stale planner fixture')
    d=json.loads(raw);digest=hashlib.sha256(raw).hexdigest();site.write('assets/chemistry/planner-v1.json',raw.decode())
    def asset(name,raw=None):
        raw=raw if raw is not None else (site.root/'website/assets'/name).read_bytes()
        return 'assets/'+name+'?v='+hashlib.sha256(raw).hexdigest()[:12]
    core=(site.root/'website/assets/chemistry-budget-core.mjs').read_text(encoding='utf-8')
    for name in ['chemistry-lab-core.mjs','chemistry-continuous-core.mjs']:
        core=core.replace("'./"+name+"'","'./"+asset(name,(site.output/'assets'/name).read_bytes()).removeprefix('assets/')+"'")
    site.write('assets/chemistry-budget-core.mjs',core)
    boot=(site.root/'website/assets/chemistry-budget.js').read_text(encoding='utf-8').replace("'./chemistry-budget-core.mjs'","'./"+asset('chemistry-budget-core.mjs',core.encode()).removeprefix('assets/')+"'")
    site.write('assets/chemistry-budget.js',boot);site.write('assets/chemistry-budget.css',(site.root/'website/assets/chemistry-budget.css').read_text(encoding='utf-8'))
    package=replay(site.root);target=site.output/'assets/chemistry/stage17-replay.zip';target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(package);package_hash=hashlib.sha256(package).hexdigest()
    for name in ['PRECISION_PLANNER.md','SELF_REVIEW.json']:
        target=site.output/'assets/chemistry/stage17'/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes((site.root/AREA/name).read_bytes())
    proof=markdown.markdown((site.root/AREA/'PRECISION_PLANNER.md').read_text(encoding='utf-8'),extensions=['fenced_code'])
    site.page(PROOF,'Planning a certified chemistry response scan','<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../../chemistry-responses.html#cr-plan">Precision planner</a> / Proof and scope</nav>'+proof+'<p><a href="../../assets/chemistry/stage17/PRECISION_PLANNER.md">Markdown source</a> · <a href="../../assets/chemistry/stage17/SELF_REVIEW.json">Project self-review</a></p>','https://github.com/KomorebiP/Operation-KOMOREBI/blob/'+site.revision+'/'+(AREA/'PRECISION_PLANNER.md').as_posix())
    report=json.loads((site.root/VERIFY/'study-001/results/checks.json').read_bytes());rows=[]
    for eta,tol in [('1/2','1/100'),('1/10','1/10'),('1/100','1/10')]:
        p=next(x['plan'] for x in report['examples'] if x['eta']==eta and x['tolerance']==tol and x['objective']=='actions')
        rows.append('<tr><th scope="row">'+str(float(F(eta)))+'</th><td>'+str(float(F(tol)))+'</td><td>'+str(p['order'])+'</td><td>'+str(p['nodes'])+' of '+str(p['saved_nodes'])+'</td></tr>')
    section='''<link rel="stylesheet" href="'''+asset('chemistry-budget.css')+'''">
<section class="cr-panel" id="cr-plan"><p class="cr-eyebrow">03 / Plan the work</p><h2>Choose the precision. See the required work.</h2><p class="bp-help">Set a maximum response radius across the whole interval. The planner chooses among the published caches and finds the smallest qualifying grid among their saved energy nodes. Hamiltonian actions and endpoint evaluations are separate costs.</p>
<div id="bp-lab" data-plan-source="'''+asset('chemistry/planner-v1.json')+'''" data-plan-sha256="'''+digest+'''" data-continuous-source="'''+asset('chemistry/continuous-v1.json')+'''" data-continuous-sha256="'''+d['continuous_data_sha256']+'''"><p id="bp-status" role="status">Loading the precision planner. The example plans and proof below are available now.</p><button id="bp-retry" type="button" hidden>Retry loading the planner</button><noscript><p>The example plans, proof and replay are available without JavaScript.</p></noscript><div id="bp-explorer" hidden>
<div class="cr-controls"><div><label for="bp-eta">Broadening η (Hartree)</label><select id="bp-eta"><option value="1/100">0.01</option><option value="1/10" selected>0.1</option><option value="1/2">0.5</option></select></div><div><label for="bp-tolerance">Maximum radius, per Hartree</label><input class="bp-input" id="bp-tolerance" type="text" inputmode="decimal" value="0.1" maxlength="80" aria-describedby="bp-help bp-error"><p class="cr-small" id="bp-help">Positive decimal or fraction, such as 0.1 or 1/100.</p></div><div><label for="bp-objective">Minimize</label><select id="bp-objective"><option value="actions">Hamiltonian actions first</option><option value="energies">Endpoint evaluations first</option></select></div></div><p id="bp-error" class="bp-error" role="alert"></p>
<p class="cr-result" id="bp-result" role="status" aria-live="polite" aria-atomic="true"></p><div id="bp-chosen"><dl class="cr-values" id="bp-values"></dl><figure class="cr-figure"><figcaption>The selected energy grid</figcaption><div id="bp-grid" class="bp-grid"></div><p class="bp-grid-legend">Tall green marks: selected nodes. Short gray marks: all saved nodes. Horizontal coordinate: removal energy ω, in Hartree.</p></figure><p><a href="chemistry-responses.html#cr-continuous" id="bp-inspect">Inspect this cache’s response</a></p></div>
<div class="cr-table" tabindex="0" role="group" aria-label="Plans for the stored caches; scroll horizontally if needed"><table><caption>Qualifying plans at the chosen broadening and radius</caption><thead><tr><th scope="col">H actions</th><th scope="col">Endpoint energies</th><th scope="col">Certified radius, per Ha</th></tr></thead><tbody id="bp-rows"></tbody></table></div>
<div class="cr-actions"><button id="bp-download" type="button" disabled>Download this scan plan</button><a id="bp-link" href="chemistry-responses.html#cr-plan">Link to these planning settings</a><button id="bp-reset" type="button">Reset planner</button></div><details><summary>Inspect the exact scan plan</summary><pre id="bp-certificate" tabindex="0" role="group" aria-label="Exact scan plan; scroll horizontally if needed"></pre></details></div></div>
<h3>Example plans from the saved data</h3><div class="cr-table" tabindex="0" role="group" aria-label="Example precision plans; scroll horizontally if needed"><table><caption>Fewest-action qualifying stored cache, then fewest saved energy nodes</caption><thead><tr><th scope="col">η (Ha)</th><th scope="col">Radius budget, per Ha</th><th scope="col">H actions</th><th scope="col">Planned energies</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div>
<p>At η = 0.1 and radius budget 0.1 per Hartree, minimizing actions gives 32 actions and 14 energies. Minimizing endpoint evaluations instead gives 64 actions and 13 energies. These are count tradeoffs; they are not measured runtime optima.</p><p>The stored endpoints have already been evaluated. This planner selects a subset for a fresh scan plan and performs zero new Hamiltonian actions. An unsupported request means these saved node pools and bounds do not certify the target. It does not establish a limit for every solver or possible grid.</p>
<details><summary>What does “smallest grid” mean?</summary><p>Every pair of saved endpoints defines a valid continuous cell. The planner uses a sharp maximum of its quadratic radius, rounded upward, as an edge weight. An exact finite minimax calculation finds the fewest nodes whose cells cover the whole interval within the requested budget. Both interval endpoints are retained. The result is optimal only among these saved nodes and published rounded bounds.</p><p>The study checks all 30,915 forward pairs, 717 frontier rows and 1,434 independent threshold tests. The browser rechecks published frontier paths with exact fractions. The proof and audits are project self-review.</p><p><a href="'''+PROOF+'''">Read the planning proof, audit and scope</a> · <a href="assets/chemistry/stage17/SELF_REVIEW.json">Read the project self-review</a></p></details>
<div class="cr-actions"><a href="assets/chemistry/stage17-replay.zip" download>Download the precision-planner replay</a><a href="assets/chemistry/planner-v1.json">Inspect the planning frontiers</a></div><p class="cr-small">Planner replay SHA-256: <code class="cr-hash">'''+package_hash+'''</code></p><p>The same fixed finite Hamiltonian, supplied source/reference and endpoint arithmetic assumptions apply. This response-radius budget is not a universal chemical-accuracy criterion.</p></section><script type="module" src="'''+asset('chemistry-budget.js',boot.encode())+'''"></script>'''
    anchor='<section class="cr-panel" id="cr-reduction">'
    if body.count(anchor)!=1:raise ValueError('Planner insertion point missing')
    body=body.replace(anchor,section+anchor).replace('03 / Test the small model','04 / Test the small model').replace('04 / Keep the assumptions with the answer','05 / Keep the assumptions with the answer').replace('<a href="#cr-continuous">Between the samples</a>','<a href="#cr-continuous">Between the samples</a><a href="#cr-plan">Plan a scan</a>')
    site.search.append(dict(title='Chemistry precision and energy-grid planner',group='Collection',kind='Examples',work_ids=[],url='chemistry-responses.html#cr-plan',text='Choose response radius tolerance action budget endpoint energy evaluations optimal saved node grid minimax scan planner exact certificate'))
    site.search.append(dict(title='Proof of saved-node precision planning',group='Collection',kind='Written proofs',work_ids=[],url=PROOF,text='Sharp quadratic radius maximum finite minimax path dynamic programming optimal saved energy grid greedy counterexample exact audit'))
    return body,dict(data_sha256=digest,replay_sha256=package_hash,replay_bytes=len(package),curves=len(d['groups']),frontier_rows=717,new_hamiltonian_actions=0)
